  }
}

async () => {
  const { spawn } = require('child_process');

  return new Promise((resolve) => {
    const bash = spawn('bash', ['/tmp/mcp-workspace/backup_md.sh']);

    let output = '';

    bash.stdout.on('data', (data) => {
      output += data.toString();
    });

    bash.stderr.on('data', (data) => {
      output += data.toString();
    });

    bash.on('close', (code) => {
      resolve({
        exitCode: code,
        output: output
      });
    });
  });
}

async () => {
  const { execSync } = require('child_process');

  try {
    // Create backup directory if it doesn't exist
    execSync('mkdir -p /tmp/mcp-workspace/backup');

    // Copy all .md files from source to backup directory
    execSync('cp /tmp/mcp-workspace/*.md /tmp/mcp-workspace/backup/', { stdio: 'pipe' });

    // List the backed up files
    const files = execSync('ls -la /tmp/mcp-workspace/backup/*.md', { encoding: 'utf-8' });

    return {
      success: true,
      message: 'Backup completed successfully!',
      files: files
    };
  } catch (error) {
    return {
      success: false,
      error: error.message
    };
  }
}

