async () => {
  const fs = require('fs');
  const path = require('path');

  try {
    // Count .md files in source directory
    const sourceFiles = fs.readdirSync('/tmp/mcp-workspace').filter(file => path.extname(file) === '.md');
    const sourceCount = sourceFiles.length;

    // Count .md files in backup directory
    const backupFiles = fs.readdirSync('/tmp/mcp-workspace/backup').filter(file => path.extname(file) === '.md');
    const backupCount = backupFiles.length;

    return {
      sourceCount: sourceCount,
      backupCount: backupCount,
      sourceFiles: sourceFiles.slice(0, 10), // Show first 10 files
      backupFiles: backupFiles.slice(0, 10)  // Show first 10 files
    };
  } catch (error) {
    return {
      error: error.message
    };
  }
}
